function doGet(e) {
  try {
    var setup = getOrCreateTargetSpreadsheet();
    return ContentService.createTextOutput(JSON.stringify({
      status: 'online',
      message: 'SCC Trust Lucky Coupon 2026 Webhook is active and operational!',
      sheetUrl: setup.ss.getUrl(),
      folderName: 'LUCKY COUPON SALE 2026',
      sheetName: 'COUPON SALE 2026',
      timestamp: new Date().toISOString()
    })).setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({
      status: 'error',
      message: err.toString()
    })).setMimeType(ContentService.MimeType.JSON);
  }
}

function doPost(e) {
  try {
    var payload = JSON.parse(e.postData.contents);
    var setup = getOrCreateTargetSpreadsheet();
    var sheet = setup.sheet;
    var targetFolder = setup.folder;

    // 1. FRESH RESTRUCTURE / RESET ALL
    if (payload.action === 'restructure' || payload.action === 'recreate') {
      sheet.clear();
      formatHeaders(sheet);
      if (payload.transactions && payload.transactions.length > 0) {
        writeAllRows(sheet, payload.transactions);
      }
      saveBackupJson(targetFolder, payload.fullBackup);
      return jsonResponse({
        status: 'success',
        message: 'Sheet restructured fresh with headers, formats and ' + (payload.transactions ? payload.transactions.length : 0) + ' records.'
      });
    }

    // 2. ULTRA-FAST SINGLE TRANSACTION ADD / UPDATE (Zero Lag)
    if (payload.action === 'add' || payload.action === 'update') {
      var tx = payload.transaction;
      if (!tx) throw new Error('Transaction data missing in payload');

      var lastRow = sheet.getLastRow();
      if (lastRow === 0) {
        formatHeaders(sheet);
        lastRow = 1;
      }

      var rowIndex = -1;
      // ALWAYS search Column B (Transaction IDs) to avoid duplicate rows whether action is 'add' or 'update'!
      if (lastRow > 1 && tx.id) {
        var idColumnValues = sheet.getRange(1, 2, lastRow, 1).getValues();
        var targetTxId = String(tx.id).trim();
        for (var i = 1; i < idColumnValues.length; i++) {
          if (String(idColumnValues[i][0]).trim() === targetTxId) {
            rowIndex = i + 1;
            break;
          }
        }
      }

      var slNo = rowIndex > 1 ? rowIndex - 1 : Math.max(1, lastRow);
      var row = [
        slNo,
        tx.id || '',
        tx.date ? new Date(tx.date).toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' }) : new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' }),
        tx.name || '',
        tx.area || '',
        tx.phone || '',
        tx.books || 0,
        tx.bookNumber || '',
        tx.coupons || 0,
        tx.couponNumber || '',
        tx.totalAmount || 0,
        tx.paidAmount || 0,
        tx.creditAmount || 0,
        tx.paymentMethod || 'CASH',
        tx.paidToTreasurer ? 'YES' : 'NO',
        new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' })
      ];

      if (rowIndex > 1) {
        sheet.getRange(rowIndex, 1, 1, row.length).setValues([row]);
      } else {
        sheet.appendRow(row);
      }
    }
    // 3. DELETE TRANSACTION
    else if (payload.action === 'delete') {
      var txId = (payload.transaction && payload.transaction.id) ? payload.transaction.id : (payload.transactionId || '');
      if (txId) {
        var lastRow = sheet.getLastRow();
        if (lastRow > 1) {
          var idColumnValues = sheet.getRange(1, 2, lastRow, 1).getValues();
          for (var i = 1; i < idColumnValues.length; i++) {
            if (String(idColumnValues[i][0]) === String(txId)) {
              sheet.deleteRow(i + 1);
              break;
            }
          }
        }
      }
    }
    // 4. FULL BULK SYNC
    else if (payload.action === 'syncAll' && payload.transactions) {
      sheet.clear();
      formatHeaders(sheet);
      writeAllRows(sheet, payload.transactions);
      saveBackupJson(targetFolder, payload.fullBackup);
    }

    // 5. UPDATE JSON BACKUP ONLY WHEN REQUESTED OR BULK SYNC
    if (payload.syncBackup || payload.action === 'syncAll' || payload.action === 'restructure') {
      if (payload.fullBackup) {
        saveBackupJson(targetFolder, payload.fullBackup);
      }
    }

    // 6. PRIZE COLLECTION SYNC
    if (payload.action === 'syncPrizes') {
      writePrizeCollectionTab(setup.ss, payload);
      return jsonResponse({
        status: 'success',
        message: 'Prize Collection synchronized to Google Sheet tab successfully!'
      });
    }

    return jsonResponse({ status: 'success', message: 'Sync successful for action: ' + payload.action });
  } catch (err) {
    return jsonResponse({ status: 'error', message: err.toString() });
  }
}

/**
 * Robust helper: Works whether script is bound to a sheet OR standalone in script.google.com!
 */
function getOrCreateTargetSpreadsheet() {
  var folderName = 'LUCKY COUPON SALE 2026';
  var sheetName = 'COUPON SALE 2026';

  var targetFolder = null;
  var folders = DriveApp.getFoldersByName(folderName);
  if (folders.hasNext()) {
    targetFolder = folders.next();
  } else {
    targetFolder = DriveApp.createFolder(folderName);
  }

  var ss = null;
  try {
    ss = SpreadsheetApp.getActiveSpreadsheet();
  } catch (e) {}

  if (ss) {
    // If bound, ensure it resides in the target folder
    try {
      var file = DriveApp.getFileById(ss.getId());
      var parents = file.getParents();
      var inFolder = false;
      while (parents.hasNext()) {
        if (parents.next().getId() === targetFolder.getId()) {
          inFolder = true;
          break;
        }
      }
      if (!inFolder) {
        targetFolder.addFile(file);
      }
    } catch (e) {}
  } else {
    // If standalone, search or create in the folder
    var sheetFiles = targetFolder.getFilesByName(sheetName);
    if (sheetFiles.hasNext()) {
      ss = SpreadsheetApp.open(sheetFiles.next());
    } else {
      ss = SpreadsheetApp.create(sheetName);
      var newFile = DriveApp.getFileById(ss.getId());
      targetFolder.addFile(newFile);
      try { DriveApp.getRootFolder().removeFile(newFile); } catch (e) {}
    }
  }

  var sheet = ss.getSheetByName(sheetName) || ss.getActiveSheet();
  if (sheet.getName() !== sheetName) {
    try { sheet.setName(sheetName); } catch (e) {}
  }

  return { ss: ss, sheet: sheet, folder: targetFolder };
}

function formatHeaders(sheet) {
  var headers = [
    'Sl No', 'Transaction ID', 'Date & Time', 'Name', 'Area', 'Phone',
    'Books', 'Book Number', 'Coupons', 'Coupon Number',
    'Total Amount (₹)', 'Paid Amount (₹)', 'Balance / Credit (₹)',
    'Payment Mode', 'Paid to Treasurer', 'System Sync Timestamp'
  ];

  sheet.getRange(1, 1, 1, headers.length).setValues([headers]);
  try {
    sheet.getRange(1, 1, 1, headers.length)
      .setBackground('#0f172a')
      .setFontColor('#ffffff')
      .setFontWeight('bold')
      .setHorizontalAlignment('center');
    sheet.setFrozenRows(1);
  } catch (e) {}
}

function writeAllRows(sheet, transactions) {
  if (!transactions || transactions.length === 0) return;
  var seenIds = {};
  var rows = [];
  var serialNo = 1;
  transactions.forEach(function(tx) {
    if (!tx) return;
    var txKey = String(tx.id || '').trim();
    if (txKey && seenIds[txKey]) return; // Skip duplicate transaction!
    if (txKey) seenIds[txKey] = true;

    rows.push([
      serialNo++,
      tx.id || '',
      tx.date ? new Date(tx.date).toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' }) : '',
      tx.name || '',
      tx.area || '',
      tx.phone || '',
      tx.books || 0,
      tx.bookNumber || '',
      tx.coupons || 0,
      tx.couponNumber || '',
      tx.totalAmount || 0,
      tx.paidAmount || 0,
      tx.creditAmount || 0,
      tx.paymentMethod || 'CASH',
      tx.paidToTreasurer ? 'YES' : 'NO',
      new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' })
    ]);
  });
  if (rows.length > 0) {
    sheet.getRange(2, 1, rows.length, rows[0].length).setValues(rows);
  }
}

function saveBackupJson(targetFolder, fullBackup) {
  if (!fullBackup || !targetFolder) return;
  var fileName = 'SCC_TRUST_LUCKY_COUPON_2026_BACKUP.json';
  var files = targetFolder.getFilesByName(fileName);
  var content = JSON.stringify(fullBackup, null, 2);
  if (files.hasNext()) {
    files.next().setContent(content);
  } else {
    targetFolder.createFile(fileName, content, MimeType.PLAIN_TEXT);
  }
}

function writePrizeCollectionTab(ss, payload) {
  var tabName = 'PRIZE COLLECTION';
  var pSheet = ss.getSheetByName(tabName);
  if (!pSheet) {
    pSheet = ss.insertSheet(tabName);
  }
  pSheet.clear();

  var tracking = payload.prizesTracking || {};
  var received = payload.receivedAmounts || [];
  var prizes = payload.prizesData || [];

  var headers = [
    'Sl No', 'Prize No', 'Prize Item', 'Display Sponsor / Donor',
    'Origin Sponsor / Remarks', 'Status', 'Trust Cost (₹)', 'Last Updated'
  ];

  var rows = [];
  rows.push(['ST. CASIMIR CHARITABLE TRUST — LUCKY DRAW 2026 PRIZE COLLECTION', '', '', '', '', '', '', '']);
  rows.push(['Last Updated: ' + new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' }), '', '', '', '', '', '', '']);
  rows.push(['', '', '', '', '', '', '', '']);
  rows.push(headers);

  prizes.forEach(function(p, idx) {
    var track = tracking[p.prize_no] || { status: 'PENDING', amount: 0 };
    var statusLabel = track.status === 'SPONSOR' ? 'SPONSOR (Collected)' : (track.status === 'TRUST' ? 'TRUST (Purchased)' : 'PENDING');
    var cost = track.status === 'TRUST' ? (Number(track.amount) || 0) : 0;
    rows.push([
      idx + 1,
      p.prize_no || '',
      p.prize_item || '',
      p.display_sponsor || '',
      p.origin_sponsor || '',
      statusLabel,
      cost,
      new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' })
    ]);
  });

  if (received && received.length > 0) {
    rows.push(['', '', '', '', '', '', '', '']);
    rows.push(['=== RECEIVED CASH DONATIONS FOR PRIZES ===', '', '', '', '', '', '', '']);
    rows.push(['Sl No', 'Donor / Contributor Name', 'Donation Amount (₹)', 'Date & Time', '', '', '', '']);
    received.forEach(function(r, rIdx) {
      rows.push([
        rIdx + 1,
        r.name || '',
        Number(r.amount) || 0,
        r.date ? new Date(r.date).toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' }) : '',
        '', '', '', ''
      ]);
    });
  }

  pSheet.getRange(1, 1, rows.length, 8).setValues(rows);

  try {
    pSheet.getRange(1, 1, 1, 8)
      .setBackground('#0f172a')
      .setFontColor('#ffffff')
      .setFontWeight('bold');
    pSheet.getRange(4, 1, 1, 8)
      .setBackground('#1e293b')
      .setFontColor('#f8fafc')
      .setFontWeight('bold');
    pSheet.setFrozenRows(4);
  } catch (e) {}
}

